import 'dart:io';
import 'package:flutter/material.dart';
import 'package:geocoding/geocoding.dart';
import 'package:geolocator/geolocator.dart';
import 'package:image_picker/image_picker.dart';
import '../../models/complaint_model.dart';
import '../../repositories/complaint_repository.dart';
import '../../services/api/api_client.dart';
import '../routes/app_routes.dart';
import '../theme/app_colors.dart';
import '../widgets/citizen_shell.dart';

class ReportIssueScreen extends StatefulWidget{const ReportIssueScreen({super.key});@override State<ReportIssueScreen> createState()=>_ReportIssueScreenState();}
class _ReportIssueScreenState extends State<ReportIssueScreen>{
 final d=TextEditingController(),a=TextEditingController();String category='POTHOLE';String? imagePath;Position? pos;bool aiLoading=false,submitting=false;String? aiCategory;double? aiConfidence;final cats=const ['POTHOLE','DAMAGED_ROAD','STREETLIGHT','GARBAGE','WATER_LEAKAGE','DRAINAGE','STRAY_ANIMAL','PUBLIC_PROPERTY_DAMAGE','OTHER'];
 Future<void> _camera()async{final result=await Navigator.pushNamed<dynamic>(context,AppRoutes.gpsCamera);if(result is! Map)return;final path=result['path']?.toString();if(path==null||path.isEmpty)return;final latitude=(result['latitude'] as num?)?.toDouble();final longitude=(result['longitude'] as num?)?.toDouble();final accuracy=(result['accuracy'] as num?)?.toDouble();setState((){imagePath=path;if(latitude!=null&&longitude!=null){pos=Position(latitude:latitude,longitude:longitude,timestamp:DateTime.now(),accuracy:accuracy??0,altitude:0,altitudeAccuracy:0,heading:0,headingAccuracy:0,speed:0,speedAccuracy:0);if((result['address']?.toString()??'').isNotEmpty)a.text=result['address'].toString();}});await _ai(path);}
 Future<void> _gallery()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:88);if(x==null)return;setState(()=>imagePath=x.path);await _ai(x.path);}
 Future<void> _ai(String path)async{setState(()=>aiLoading=true);try{final r=await ApiClient().uploadFile('/ai/verify-image',filePath:path,field:'file');final m=Map<String,dynamic>.from(ApiClient().unwrap(r.data) as Map);setState((){aiCategory=m['detectedCategory']?.toString();aiConfidence=(m['confidence'] as num?)?.toDouble();});}catch(_){setState(()=>aiCategory=null);}if(mounted)setState(()=>aiLoading=false);}
 Future<void> _gps()async{try{if(!await Geolocator.isLocationServiceEnabled())throw Exception('Enable GPS first.');var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever)throw Exception('Location permission is required.');final p2=await Geolocator.getCurrentPosition();String addr='';try{final ms=await placemarkFromCoordinates(p2.latitude,p2.longitude);if(ms.isNotEmpty){final m=ms.first;addr=[m.street,m.locality,m.administrativeArea].whereType<String>().where((x)=>x.isNotEmpty).join(', ');}}catch(_){ }setState((){pos=p2;if(addr.isNotEmpty)a.text=addr;});}catch(e){_msg(e.toString());}}
 Future<void> _submit()async{if(imagePath==null||pos==null||d.text.trim().isEmpty||a.text.trim().isEmpty){_msg('Add a photo, description and GPS location.');return;}setState(()=>submitting=true);try{final c=await RealComplaintRepository(ApiClient()).submitComplaint(category:category,description:d.text.trim(),imagePath:imagePath!,latitude:pos!.latitude,longitude:pos!.longitude,address:a.text.trim(),categorySource:aiCategory==null?'MANUAL':'AI',aiDetectedCategory:aiCategory,aiConfidence:aiConfidence,locationAccuracy:pos!.accuracy);if(!mounted)return;Navigator.pushReplacementNamed(context,AppRoutes.complaintDetails,arguments:c.id);}catch(e){_msg(e.toString());}if(mounted)setState(()=>submitting=false);}
 void _msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
 @override Widget build(BuildContext context)=>CitizenShell(index:2,title:'MY CITY CONNECT  •  REPORT CIVIC ISSUE',child:ListView(padding:const EdgeInsets.fromLTRB(16,8,16,30),children:[
  Row(children:[_step('1',true,'Photo'),_line(),_step('2',true,'Issue'),_line(),_step('3',false,'Location'),_line(),_step('4',false,'Review'),_line(),_step('5',false,'Submit')]),const SizedBox(height:14),
  _section('STEP 1: ISSUE EVIDENCE'),
  InkWell(onTap:_camera,borderRadius:BorderRadius.circular(14),child:Container(height:170,decoration:BoxDecoration(color:const Color(0xFFF2F6FB),borderRadius:BorderRadius.circular(14),border:Border.all(color:AppColors.cardBorder)),child:imagePath==null?const Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(Icons.gps_fixed_rounded,size:38,color:Color(0xFF1477B8)),SizedBox(height:8),Text('Capture with GPS Camera',style:TextStyle(fontWeight:FontWeight.w800,fontSize:13)),SizedBox(height:3),Text('Photo + current GPS coordinates',style:TextStyle(fontSize:10,color:AppColors.textSecondary))]):ClipRRect(borderRadius:BorderRadius.circular(13),child:Image.file(File(imagePath!),width:double.infinity,height:170,fit:BoxFit.cover)))),
  Padding(padding:const EdgeInsets.only(top:8),child:Row(children:[Expanded(child:OutlinedButton.icon(onPressed:_camera,icon:const Icon(Icons.gps_fixed_rounded),label:Text(imagePath==null?'OPEN GPS CAMERA':'RETAKE GPS PHOTO'))),const SizedBox(width:8),Expanded(child:OutlinedButton.icon(onPressed:_gallery,icon:const Icon(Icons.photo_library_outlined),label:Text(imagePath==null?'UPLOAD PHOTO':'UPLOAD DIFFERENT')))])),
  const SizedBox(height:12),
  if(aiLoading)const _AiCard(loading:true) else if(aiConfidence!=null)_AiCard(category:aiCategory,confidence:aiConfidence),
  const SizedBox(height:14),_section('STEP 2: ISSUE CATEGORY'),
  DropdownButtonFormField<String>(initialValue:category,items:cats.map((c)=>DropdownMenuItem(value:c,child:Text(c.replaceAll('_',' '),style:const TextStyle(fontSize:12)))).toList(),onChanged:(v)=>setState(()=>category=v??category),decoration:const InputDecoration(prefixIcon:Icon(Icons.category_outlined),labelText:'Problem Category')),
  const SizedBox(height:12),TextField(controller:d,maxLines:4,decoration:const InputDecoration(labelText:'Describe the problem',hintText:'Tell us what is happening...')),
  const SizedBox(height:12),_section('STEP 3: GPS LOCATION'),
  OutlinedButton.icon(onPressed:_gps,icon:const Icon(Icons.my_location_rounded),label:Text(pos==null?'Capture current location':'GPS location captured')),
  if(pos!=null)Padding(padding:const EdgeInsets.only(top:8),child:Text('${pos!.latitude.toStringAsFixed(6)}, ${pos!.longitude.toStringAsFixed(6)}  •  ±${pos!.accuracy.toStringAsFixed(1)} m',style:const TextStyle(fontSize:10,color:AppColors.textSecondary))),
  const SizedBox(height:10),TextField(controller:a,maxLines:2,decoration:const InputDecoration(labelText:'Address / landmark')),
  const SizedBox(height:18),SizedBox(height:52,child:ElevatedButton(onPressed:submitting?null:_submit,child:submitting?const CircularProgressIndicator(color:Colors.white):const Text('CONTINUE  →',style:TextStyle(fontWeight:FontWeight.w900))))
 ]));
 Widget _section(String s)=>Padding(padding:const EdgeInsets.only(bottom:8),child:Text(s,style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900,color:AppColors.textSecondary)));
 Widget _step(String n,bool active,String l)=>Column(children:[CircleAvatar(radius:13,backgroundColor:active?const Color(0xFF1DB77A):const Color(0xFFE5EAF1),child:Text(n,style:TextStyle(fontSize:9,fontWeight:FontWeight.w900,color:active?Colors.white:AppColors.textSecondary))),const SizedBox(height:3),Text(l,style:const TextStyle(fontSize:7,color:AppColors.textSecondary))]);Widget _line()=>Expanded(child:Container(height:1,margin:const EdgeInsets.only(bottom:16),color:AppColors.cardBorder));
 @override void dispose(){d.dispose();a.dispose();super.dispose();}
}
class _AiCard extends StatelessWidget{final bool loading;final String? category;final double? confidence;const _AiCard({this.loading=false,this.category,this.confidence});@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:const Color(0xFFE9FFF4),borderRadius:BorderRadius.circular(13),border:Border.all(color:const Color(0xFFBDEFD5))),child:Row(children:[const Icon(Icons.verified_rounded,color:Color(0xFF16A56C),size:20),const SizedBox(width:8),Expanded(child:loading?const Text('AI is analyzing the evidence photo...',style:TextStyle(fontSize:10,fontWeight:FontWeight.w700)):Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('AI VERIFICATION',style:TextStyle(fontSize:8,fontWeight:FontWeight.w900,color:Color(0xFF148D5A))),Text(category==null?'Manual category confirmation required':'${category!.replaceAll('_',' ')} detected',style:const TextStyle(fontSize:11,fontWeight:FontWeight.w800)),if(confidence!=null)Text('${(confidence!*100).toStringAsFixed(0)}% confidence',style:const TextStyle(fontSize:9,color:AppColors.textSecondary))]))]));}
